// Derived binary stores (R0-2): exclude and purge delete every store in
// the shared inventory wholesale, and later rebuilds honor tombstones at
// build time, so a store file that still predates the newest tombstone is
// exactly the failed/locked deletion this check exists to catch. A store
// recreated after cleanup is clean by construction.
var newestID string
var newestAt time.Time
for id, stone := range stones.Excluded {
	if stone.At.After(newestAt) {
		newestID, newestAt = id, stone.At
	}
