19	// conversational-memory plan: brain-local session tombstones understood before
20	// derived indexing, plus list/exclude/include/purge administration with
21	// dry-run.
22	//
23	// Authority model: the tombstone is brain-local (the plan's resolved default
24	// until a capture-layer exclusion contract exists in the Entire CLI). Purge
25	// physically deletes the brain's LOCAL projections; the exported transcript
26	// copy under sessions/ and every derived store built from it; and the
27	// tombstone prevents re-indexing even if a later `refresh sessions` re-exports
28	// the still-canonical captured material. Deleting the canonical capture itself
29	// is the capture layer's job, not the brain's.
30	
31	const (
32		sessionTombstonesFileName = "tombstones.json"
33		sessionTombstonesPath     = historyDirName + "/" + sessionTombstonesFileName
34		sessionTombstonesVersion  = 1
35	)
36	
37	type sessionTombstones struct {
38		Version int `json:"version"`
39		// Excluded maps session_id -> tombstone. Content-free by design: a
40		// tombstone must never retain what it excludes.
41		Excluded map[string]sessionTombstone `json:"excluded"`
42	}
43	
44	type sessionTombstone struct {
45		At     time.Time `json:"at"`
46		Reason string    `json:"reason,omitempty"`
47	}
48	
49	// loadSessionTombstones always returns a usable value; a missing or corrupt
50	// file reads as "nothing excluded" (exclusion is an explicit user action, so
51	// failing open here only ever restores default indexing, never deletes data).
52	func loadSessionTombstones(brainDir string) sessionTombstones {
53		empty := sessionTombstones{Version: sessionTombstonesVersion, Excluded: map[string]sessionTombstone{}}
54		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(sessionTombstonesPath)))
55		if err != nil {
56			return empty
57		}
58		var stones sessionTombstones
59		if err := json.Unmarshal(data, &stones); err != nil || stones.Excluded == nil {
60			return empty
61		}
62		return stones
63	}
64	
65	func saveSessionTombstones(brainDir string, stones sessionTombstones) error {
66		stones.Version = sessionTombstonesVersion
67		data, err := json.MarshalIndent(stones, "", "  ")
68		if err != nil {
69			return err
70		}
71		return writeBrainRelativeFileAtomic(brainDir, sessionTombstonesPath, append(data, '\n'), 0o600)
72	}
