74	// excludedTranscriptPaths resolves the brain-relative transcript paths that
75	// belong to excluded sessions, from the trusted manifest only.
76	func excludedTranscriptPaths(manifest *exportManifest, stones sessionTombstones) map[string]string {
77		out := map[string]string{}
78		if len(stones.Excluded) == 0 || manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
79			return out
80		}
81		for _, session := range manifest.Sources.Sessions.Sessions {
82			id := strings.TrimSpace(session.SessionID)
83			if id == "" {
84				continue
85			}
86			if _, excluded := stones.Excluded[id]; !excluded {
87				continue
88			}
89			rel := filepath.ToSlash(strings.TrimSpace(session.TranscriptPath))
90			if rel != "" {
91				out[rel] = id
92			}
93		}
94		return out
95	}
