		entries = append(entries, contextEntry{turn: expand(view.Records[targetIndex-offset]), distance: offset, index: targetIndex - offset})
	}
	for offset := 1; offset <= wantAfter; offset++ {
		entries = append(entries, contextEntry{turn: expand(view.Records[targetIndex+offset]), distance: offset, index: targetIndex + offset})
	}
