			total += turnJSONBytes(entry.turn)
		}
		if total <= budget || len(entries) == 0 {
			break
		}
		farthest := 0
		for i, entry := range entries {
			if entry.distance > entries[farthest].distance {
				farthest = i
			}
		}
		if entries[farthest].index < targetIndex {
			result.OmittedBefore++
		} else {
			result.OmittedAfter++
		}
