			if r, ok := convByID[id]; ok {
				found = append(found, conversationGetResult(brainDir, r))
				continue
			}
		case strings.HasPrefix(id, "doc:"):
			if r, ok := docByID[strings.TrimPrefix(id, "doc:")]; ok {
				found = append(found, docToUnified(r))
				continue
