		// newest-copy winner ranking uses, so get expands exactly the
		// record search returned (R0-4).
		for _, r := range fresh.reconciledRecords() {
			if guard.blocksRecord(r) {
				continue
			}
			if r.Kind == conversationKind {
				convByID[r.ID] = r
				continue
			}
			histByID[r.ID] = r
		}
	}
}

