197	// dispatchMCPMessage performs the actual request routing. handleMCPMessage wraps
198	// it with panic recovery; it is a package var so tests can inject a panicking
199	// handler to verify that recovery keeps the server alive. Tests that reassign it
200	// must not run with t.Parallel() — the server itself only ever reads it.
201	var dispatchMCPMessage = func(ctx context.Context, opts Options, msg mcpMessage) mcpMessage {
202		response := mcpMessage{JSONRPC: "2.0", ID: msg.ID}
203		switch msg.Method {
204		case "initialize":
205			protocolVersion := mcpInitializeProtocolVersion(msg.Params)
206			response.Result = map[string]any{
207				"protocolVersion": protocolVersion,
208				"capabilities":    map[string]any{"tools": map[string]any{}},
209				"serverInfo":      map[string]any{"name": "entire-brain", "version": opts.Version},
210			}
211		case "tools/list":
212			response.Result = map[string]any{"tools": mcpToolDefinitions()}
213		case "tools/call":
214			result, err := handleMCPToolCall(ctx, opts, msg.Params)
215			if err != nil {
216				response.Error = &mcpError{Code: -32000, Message: err.Error()}
217			} else {
218				response.Result = result
219			}
220		default:
221			response.Error = &mcpError{Code: -32601, Message: "method not found"}
222		}
223		return response
224	}
